package io.knowledgebrain.planning;
import java.util.*;import java.util.concurrent.*;import java.time.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_DATABASE_URL",matches=".+")
class TaskStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;TaskStore store;GoalStore goals;String schema;final UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;final String trace="b".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));schema="task_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new TaskStore(ds,Clock.systemUTC());goals=new GoalStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void cleanup(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 TaskStore.Input input(String title,UUID goal){return new TaskStore.Input(title," description\n","NOT_STARTED","1582-10-10",goal);}
 GoalStore.Goal goal(UUID scope){return goals.create(scope,actor,key(),new GoalStore.Input("Goal","","NOT_STARTED",null),trace).goal();}
 void status(int status,Runnable work){assertEquals(status,assertThrows(ResponseStatusException.class,work::run).getStatusCode().value());}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 int events(){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='task'",Integer.class);}
 @Test void createRetrySurvivesParentRetirementEditsArchiveAndPrincipalClaim(){var g=goal(space);String key=key();var original=store.create(space,actor,key,input("Task",g.goalId()),trace);assertFalse(original.replay());goals.change(space,g.goalId(),actor,1,null,true,trace);var priorGoal=goals.history(space,g.goalId(),Long.MAX_VALUE,5);var changed=store.change(space,original.task().taskId(),ids.next(),1,new TaskStore.Input("Completed","","COMPLETED",null,g.goalId()),false,trace);assertNull(changed.dueDate());assertEquals(g.goalId(),changed.goalId());assertEquals(original.task(),store.create(space,ids.next(),key,input("Task",g.goalId()),trace).task());status(409,()->store.create(space,actor,key,input("Other",g.goalId()),trace));store.change(space,changed.taskId(),actor,2,null,true,trace);assertEquals(original.task(),store.create(space,actor,key,input("Task",g.goalId()),trace).task());status(404,()->store.get(space,changed.taskId()));assertEquals(changed.taskId(),store.list(space,"RETIRED","COMPLETED",g.goalId().toString(),null,20).items().getFirst().taskId());assertEquals(1,count("task"));assertEquals(3,count("task_revision"));assertEquals(3,events());assertEquals(priorGoal,goals.history(space,g.goalId(),Long.MAX_VALUE,5));assertEquals(List.of(3L,2L,1L),store.history(space,changed.taskId(),Long.MAX_VALUE,5).stream().map(TaskStore.Revision::version).toList());}
 @Test void goalReferencesAreSameSpaceAndNewLinksRequireActiveButRetainedLinksAndUnlinkWork(){var g=goal(space);var foreign=goal(actor);for(UUID denied:List.of(foreign.goalId(),ids.next()))status(404,()->store.create(space,actor,key(),input("Denied",denied),trace));assertEquals(0,count("task"));assertEquals(0,events());var task=store.create(space,actor,key(),input("Own",g.goalId()),trace).task();status(404,()->store.change(actor,task.taskId(),actor,1,input("Foreign",null),false,trace));status(404,()->store.history(actor,task.taskId(),Long.MAX_VALUE,5));status(404,()->store.change(space,task.taskId(),actor,1,input("Wrong",foreign.goalId()),false,trace));assertEquals(task,store.get(space,task.taskId()));goals.change(space,g.goalId(),actor,1,null,true,trace);status(404,()->store.create(space,actor,key(),input("Retired",g.goalId()),trace));var unlinked=store.change(space,task.taskId(),actor,1,input("Unlinked",null),false,trace);assertNull(unlinked.goalId());status(404,()->store.change(space,task.taskId(),actor,2,input("Relink",g.goalId()),false,trace));assertEquals(unlinked,store.get(space,task.taskId()));assertEquals(g.goalId(),store.history(space,task.taskId(),Long.MAX_VALUE,5).getLast().snapshot().goalId());assertThrows(RuntimeException.class,()->sql.update("UPDATE task SET goal_id=? WHERE task_id=?",foreign.goalId(),task.taskId()));assertNull(store.get(space,task.taskId()).goalId());}
 @Test void independentNoopStaleDatesCatalogAndHistoryPages(){var g=goal(space);var gBefore=goals.get(space,g.goalId());var selected=store.create(space,actor,key(),input("Task",g.goalId()),trace).task();assertEquals(selected,store.change(space,selected.taskId(),actor,1,input("Task",g.goalId()),false,trace));status(412,()->store.change(space,selected.taskId(),actor,2,input("Task",g.goalId()),false,trace));for(int i=0;i<22;i++)store.create(space,actor,key(),input("Task "+i,i%2==0?g.goalId():null),trace);var a=store.list(space,"ACTIVE","ALL","ALL",null,20);assertEquals(20,a.items().size());var b=store.list(space,"ACTIVE","ALL","ALL",a.nextAfter(),20);assertEquals(3,b.items().size());assertNull(b.nextAfter());assertEquals(11,store.list(space,"ACTIVE","ALL","NONE",null,100).items().size());assertEquals(12,store.list(space,"ACTIVE","ALL",g.goalId().toString(),null,100).items().size());for(int v=1;v<9;v++)store.change(space,selected.taskId(),actor,v,new TaskStore.Input("Version "+(v+1),"","COMPLETED",null,g.goalId()),false,trace);assertEquals(1,store.list(space,"ACTIVE","COMPLETED","ALL",null,100).items().size());assertEquals(List.of(9L,8L,7L,6L,5L),store.history(space,selected.taskId(),Long.MAX_VALUE,5).stream().map(TaskStore.Revision::version).toList());assertEquals(List.of(4L,3L,2L,1L),store.history(space,selected.taskId(),5,5).stream().map(TaskStore.Revision::version).toList());assertEquals(gBefore,goals.get(space,g.goalId()));ds.setOptions("-c TimeZone=America/New_York");for(String date:List.of("0001-01-01","1582-10-10","9999-12-31")){var v=store.create(space,actor,key(),new TaskStore.Input("Date","","NOT_STARTED",date,null),trace).task();assertEquals(date,sql.queryForObject("SELECT due_date::text FROM task WHERE task_id=?",String.class,v.taskId()));assertEquals(date,store.list(space,"ACTIVE","ALL","NONE",null,100).items().stream().filter(x->x.taskId().equals(v.taskId())).findFirst().orElseThrow().dueDate());}}
 @Test void outboxFailureRollsBackCreateUpdateAndRetirement(){var existing=store.create(space,actor,key(),input("Existing",null),trace).task();sql.execute("CREATE FUNCTION fail_task_outbox() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled outbox failure'; END $$");sql.execute("CREATE TRIGGER fail_task_outbox BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_task_outbox()");assertThrows(RuntimeException.class,()->store.create(space,actor,key(),input("Failed",null),trace));assertThrows(RuntimeException.class,()->store.change(space,existing.taskId(),actor,1,input("Failed",null),false,trace));assertThrows(RuntimeException.class,()->store.change(space,existing.taskId(),actor,1,null,true,trace));assertEquals(existing,store.get(space,existing.taskId()));assertEquals(1,count("task"));assertEquals(1,count("task_revision"));assertEquals(1,events());}
 @Test void concurrentRequestsHaveOneCanonicalWinner()throws Exception{var g=goal(space);String key=key();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var a=pool.submit(()->{gate.await();return store.create(space,actor,key,input("Task",g.goalId()),trace);});var b=pool.submit(()->{gate.await();return store.create(space,actor,key,input("Task",g.goalId()),trace);});var one=a.get();var two=b.get();assertEquals(one.task(),two.task());assertNotEquals(one.replay(),two.replay());var start=new CyclicBarrier(2);var results=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++){final int n=i;results.add(pool.submit(()->{start.await();try{store.change(space,one.task().taskId(),actor,1,input("Concurrent "+n,g.goalId()),false,trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));}assertEquals(Set.of(200,412),Set.of(results.get(0).get(),results.get(1).get()));assertEquals(1,count("task"));assertEquals(2,count("task_revision"));assertEquals(2,events());}}
}
